from scipy.optimize import least_squares
import warnings; warnings.filterwarnings('ignore')
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
V=np.var(y)
fams={
 'P t exp(-k t)': (lambda p: P*t*np.exp(-p[3]*t), 1),
 'P sin(k t)': (lambda p: P*np.sin(p[3]*t), 1),
 'P t^k': (lambda p: P*t**p[3], 1),
 'P*exp(-k t)': (lambda p: P*np.exp(-p[3]*t), 1),
 't^k': (lambda p: t**p[3], 1),
 'P t^2 exp': (lambda p: P*t**2*np.exp(-p[3]*t),1),
 'P*logt*... (t/(1+kt))': (lambda p: P*t/(1+p[3]*t),1),
 'P^k t': (lambda p: P**p[3]*t,1),
 'P t/(1+kP)': (lambda p: P*t/(1+p[3]*P),1),
 'P^2 t/(1+kt)': (lambda p: P**2*t/(1+p[3]*t),1),
 'P log(1+k t)': (lambda p: P*np.log(1+p[3]*t),1),
 'P cos(k t)': (lambda p: P*np.cos(p[3]*t),1),
}
out=[]
for name,(F,_) in fams.items():
    bestr=(9,None)
    for k0 in [0.1,0.5,1,2,3]:
        for c0 in [0.3,1,2]:
            def res(p):
                return p[0]*P**2+p[1]*t*np.log(1+p[2]*P)+p[4]*F(p)-y
            try:
                s=least_squares(res,[0.5,0.5,c0,k0,0.5],max_nfev=400)
                v=np.mean(s.fun**2)/V
                if np.isfinite(v) and v<bestr[0]: bestr=(v,np.round(s.x,4))
            except Exception as e: pass
    out.append((name,bestr))
for o in out: print(o)

